create table pw_commission_rule (id bigint generated by default as identity primary key,rule_code varchar(32) not null unique,rule_name varchar(64) not null,commission_rate decimal(6,4) not null,min_withdraw_amount decimal(14,2) not null,withdraw_weekday integer not null,enabled boolean not null default true,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create table pw_player_account (id bigint generated by default as identity primary key,player_id bigint not null unique,available_balance decimal(14,2) not null default 0,frozen_balance decimal(14,2) not null default 0,total_income decimal(14,2) not null default 0,total_withdrawn decimal(14,2) not null default 0,version bigint not null default 0,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create table pw_player_earning (id bigint generated by default as identity primary key,earning_no varchar(48) not null unique,order_id bigint not null unique,player_id bigint not null,order_amount decimal(14,2) not null,commission_rate decimal(6,4) not null,commission_amount decimal(14,2) not null,player_amount decimal(14,2) not null,earning_status varchar(20) not null,settled_at timestamp,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create table pw_withdrawal_request (id bigint generated by default as identity primary key,withdrawal_no varchar(48) not null unique,player_id bigint not null,amount decimal(14,2) not null,payout_method varchar(32) not null,account_name varchar(64) not null,account_no varchar(128) not null,withdrawal_status varchar(20) not null,review_remark varchar(500),reviewed_by bigint,reviewed_at timestamp,created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create index ix_pw_withdrawal_player on pw_withdrawal_request(player_id,id);
create table pw_player_account_transaction (id bigint generated by default as identity primary key,transaction_no varchar(48) not null unique,account_id bigint not null,player_id bigint not null,balance_type varchar(16) not null,direction varchar(8) not null,business_type varchar(32) not null,business_no varchar(48) not null,amount decimal(14,2) not null,balance_before decimal(14,2) not null,balance_after decimal(14,2) not null,remark varchar(500),created_at timestamp not null default current_timestamp);
create index ix_pw_player_account_tx on pw_player_account_transaction(player_id,id);

insert into pw_commission_rule(rule_code,rule_name,commission_rate,min_withdraw_amount,withdraw_weekday) values('DEFAULT','平台默认抽佣规则',0.28,300,1);
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','PlayerSettlement','settlement','/player/settlement','我的收益','ri:money-cny-circle-line',2 from sys_menu where name='PlayerPortal' and not exists(select 1 from sys_menu where name='PlayerSettlement');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat('PlayerSettlement',a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'View' suffix,'查看收益' title,'player:settlement:view' mark,1 sort_no union all select 'Withdraw' suffix,'申请提现' title,'player:withdraw:create' mark,2 sort_no) a on 1=1 where p.name='PlayerSettlement' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','SettlementManage','settlement-manage','/business/settlement-manage','结算管理','ri:secure-payment-line',12 from sys_menu where name='Business' and not exists(select 1 from sys_menu where name='SettlementManage');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat('SettlementManage',a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'List' suffix,'查询提现' title,'business:settlement:list' mark,1 sort_no union all select 'Audit' suffix,'审核提现' title,'business:settlement:audit' mark,2 sort_no union all select 'Export' suffix,'导出结算报表' title,'business:settlement:export' mark,3 sort_no union all select 'Rule' suffix,'维护抽佣规则' title,'business:settlement:rule' mark,4 sort_no) a on 1=1 where p.name='SettlementManage' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code in('player','admin') and (m.name='PlayerSettlement' or m.auth_mark like 'player:settlement:%' or m.auth_mark like 'player:withdraw:%') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and (m.name='SettlementManage' or m.auth_mark like 'business:settlement:%') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
